def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_prev, opp_prev = history[-1]

    opp_d = 0
    for _, b in history:
        if b == 'D':
            opp_d += 1

    recent = history[-10:] if n >= 10 else history
    recent_opp_d = sum(1 for _, b in recent if b == 'D')

    consec_d = 0
    for _, b in reversed(history):
        if b == 'D':
            consec_d += 1
        else:
            break

    punish = 0
    forgive = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'D':
                punish += 1
            else:
                forgive += 1

    if opp_d == 0 and n >= 50:
        return 'D'

    if opp_d <= 1 and n >= 85 and opp_prev == 'C' and punish == 0 and forgive >= 1:
        return 'D'

    if opp_d * 3 > n * 2 or recent_opp_d >= 5:
        return 'D'

    if consec_d >= 3:
        return 'D'

    if opp_prev == 'D':
        if n >= 2 and history[-2][0] == 'D' and opp_d <= 4:
            return 'C'
        if opp_d <= 2 and recent_opp_d <= 1 and forgive > punish:
            return 'C'
        return 'D'

    return 'C'
